public class ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}

public ListNode reverseKGroup(ListNode head, int k) {
    ListNode dummy = new ListNode(0, head);
    ListNode groupPrev = dummy;
    while (true) {
        // 1) Verify k nodes remain; kth is the block's last node.
        ListNode kth = groupPrev;
        for (int i = 0; i < k && kth != null; i++) {
            kth = kth.next;
        }
        if (kth == null) {
            break; // fewer than k left -> leave as is
        }
        ListNode groupNext = kth.next;
        // 2) Reverse the block; prev seeded to groupNext wires the tail.
        ListNode prev = groupNext;
        ListNode curr = groupPrev.next;
        while (curr != groupNext) {
            ListNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        // 3) Stitch: prev block tail -> new head; advance groupPrev.
        ListNode tmp = groupPrev.next; // old head, now the block's tail
        groupPrev.next = kth;          // kth is the block's new head
        groupPrev = tmp;
    }
    return dummy.next;
}

public ListNode reverseKGroup(ListNode head, int k) {
    // Base case + remainder rule: fewer than k nodes -> leave as is.
    ListNode node = head;
    for (int i = 0; i < k; i++) {
        if (node == null) {
            return head;
        }
        node = node.next;
    }
    // Reverse the first k nodes.
    ListNode prev = null;
    ListNode curr = head;
    for (int i = 0; i < k; i++) {
        ListNode next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
    }
    // head is now this block's tail; link it to the processed remainder.
    head.next = reverseKGroup(curr, k);
    return prev; // new head of this block
}

